// ServerInterface represents all server handlers.
type ServerInterface interface {
	// 本域进程存活
	// (GET /healthz)
	Health(w http.ResponseWriter, r *http.Request)
	// 本域启动/恢复就绪
	// (GET /readyz)
	Ready(w http.ResponseWriter, r *http.Request)
	// 取得jobs本域屏障
	// (POST /v1/barriers)
	AcquireBarrier(w http.ResponseWriter, r *http.Request, params AcquireBarrierParams)
	// 解除全域任务暂停
	// (POST /v1/barriers/{barrierId}:release)
	ReleaseBarrier(w http.ResponseWriter, r *http.Request, barrierId string, params ReleaseBarrierParams)
	// 等待全域安全点
	// (POST /v1/barriers:coordinate)
	CoordinateBarrier(w http.ResponseWriter, r *http.Request, params CoordinateBarrierParams)
	// 查看死信投递
	// (GET /v1/deliveries)
	ListDeliveries(w http.ResponseWriter, r *http.Request, params ListDeliveriesParams)
	// 重放死信投递
	// (POST /v1/deliveries/{deliveryId}:replay)
	ReplayDelivery(w http.ResponseWriter, r *http.Request, deliveryId string)
	// 持久接收事件
	// (POST /v1/events)
	PublishEvent(w http.ResponseWriter, r *http.Request, params PublishEventParams)
	// 消费者确认投递
	// (POST /v1/events/{eventId}:ack)
	AcknowledgeEvent(w http.ResponseWriter, r *http.Request, eventId string, params AcknowledgeEventParams)
	// 已登记消费者订阅事件SSE
	// (GET /v1/events:subscribe)
	SubscribeEvents(w http.ResponseWriter, r *http.Request, params SubscribeEventsParams)
	// 查看任务队列
	// (GET /v1/jobs)
	ListJobs(w http.ResponseWriter, r *http.Request, params ListJobsParams)
	// 持久提交任务
	// (POST /v1/jobs)
	CreateJob(w http.ResponseWriter, r *http.Request, params CreateJobParams)
	// 读取管理任务状态
	// (GET /v1/jobs/{jobId})
	ReadJob(w http.ResponseWriter, r *http.Request, jobId string, params ReadJobParams)
	// 写回前检验执行权
	// (GET /v1/jobs/{jobId}/lease)
	CheckLease(w http.ResponseWriter, r *http.Request, jobId string, params CheckLeaseParams)
	// 任务进度SSE
	// (GET /v1/jobs/{jobId}/progress)
	StreamProgress(w http.ResponseWriter, r *http.Request, jobId string, params StreamProgressParams)
	// 请求取消任务
	// (POST /v1/jobs/{jobId}:cancel)
	CancelJob(w http.ResponseWriter, r *http.Request, jobId string, params CancelJobParams)
	// 提交成功结果
	// (POST /v1/jobs/{jobId}:complete)
	CompleteJob(w http.ResponseWriter, r *http.Request, jobId string, params CompleteJobParams)
	// 失败写回
	// (POST /v1/jobs/{jobId}:fail)
	FailJob(w http.ResponseWriter, r *http.Request, jobId string, params FailJobParams)
	// 维持租约
	// (POST /v1/jobs/{jobId}:heartbeat)
	HeartbeatJob(w http.ResponseWriter, r *http.Request, jobId string, params HeartbeatJobParams)
	// 重试失败任务
	// (POST /v1/jobs/{jobId}:retry)
	RetryJob(w http.ResponseWriter, r *http.Request, jobId string)
	// 确认开始执行
	// (POST /v1/jobs/{jobId}:start)
	StartJob(w http.ResponseWriter, r *http.Request, jobId string, params StartJobParams)
	// 领取待执行任务
	// (POST /v1/jobs:claim)
	ClaimJob(w http.ResponseWriter, r *http.Request, params ClaimJobParams)
	// 查看定时任务
	// (GET /v1/schedules)
	ListSchedules(w http.ResponseWriter, r *http.Request)
	// 创建定时任务
	// (POST /v1/schedules)
	CreateSchedule(w http.ResponseWriter, r *http.Request, params CreateScheduleParams)
	// 修改定时CAS
	// (PUT /v1/schedules/{scheduleId})
	UpdateSchedule(w http.ResponseWriter, r *http.Request, scheduleId string, params UpdateScheduleParams)
	// 删除恢复暂存或换出的旧数据目录
	// (POST /v1/snapshots:discard)
	DiscardSnapshot(w http.ResponseWriter, r *http.Request, params DiscardSnapshotParams)
	// 导出队列与事件一致快照
	// (POST /v1/snapshots:export)
	ExportSnapshot(w http.ResponseWriter, r *http.Request, params ExportSnapshotParams)
	// 暂存本域恢复归档，不改active目录
	// (POST /v1/snapshots:stage)
	StageSnapshot(w http.ResponseWriter, r *http.Request, params StageSnapshotParams)
}

